sql.where:
p.del_yn = 'N'

  AND p.person_type = #{personType}



    AND p.person_id LIKE '%' + #{keyword} + '%'
    AND p.person_name = #{keywordEnc}

      AND EXISTS (SELECT 1 FROM tb_card cd WHERE cd.person_id = p.person_id AND cd.del_yn = 'N'
                  AND cd.biostar_card_value LIKE '%' + #{keyword} + '%')


      AND (p.person_id LIKE '%' + #{keyword} + '%'
           OR p.person_name = #{keywordEnc}
           OR EXISTS (SELECT 1 FROM tb_card cd WHERE cd.person_id = p.person_id AND cd.del_yn = 'N'
                      AND cd.biostar_card_value LIKE '%' + #{keyword} + '%'))




  AND p.company_code = #{companyCode}


  AND p.status_code = #{statusCode}

mapper.select:
SELECT person_id FROM tb_person
WHERE del_yn = 'N' AND person_id IN
#{id}

SELECT CONVERT(varchar(19), access_start_dt, 126) AS access_start_dt,
       CONVERT(varchar(19), access_end_dt, 126)   AS access_end_dt
FROM tb_person WHERE person_id = #{personId}

mapper.update:
